import{_ as r,l as i,o as a,c as s,v as l,p as n,x as t,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"多样本聚合与投票","description":"","frontmatter":{"title":"多样本聚合与投票","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/multi-sample-aggregation.md","filePath":"llm/multi-sample-aggregation.md","lastUpdated":1789023840000}'),c={name:"llm/multi-sample-aggregation.md"};function h(N,e,B,f,u,E){const o=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=l('<h1 id="多样本聚合与投票" tabindex="-1">多样本聚合与投票 <a class="header-anchor" href="#多样本聚合与投票" aria-label="Permalink to &quot;多样本聚合与投票&quot;">​</a></h1><div class="epigraph"><p>把同一问题的许多条思维链投进答案空间：错的分散，对的汇聚；聚合函数选得不对，N 只是把系统性偏差选稳。</p><footer>—— Wang et al., Self-Consistency, ICLR 2023；核对器上的多样本见 Cobbe et al., 2021 与 Best-of-N</footer></div><p><a href="/llm/structured-output-overhead">上一课</a>用掩码保证 <em>一条</em> 输出合法。本课关闭「解码进阶」：质量也可以买宽度——独立采样 \\(N\\) 条，在答案空间或打分器上聚合。主干已有 <a href="/llm/self-consistency">Self-Consistency</a> 与 <a href="/llm/best-of-n">Best-of-N</a>；这里不重推多数票公式，只补本课序留下的缺口：何时投票、何时 MBR、何时 BoN，以及 \\(N\\) 如何打在 KV 与延迟上。下一课程「推理系统进阶」从<a href="/llm/kv-cache-size-math">把 KV 字节算清楚</a>开始，因为投票把 \\(N\\) 放大之前必须先会算一份缓存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结构化输出解决解析，不解决算错。单次贪心把早期错误写圆，<a href="/llm/temperature-reasoning">温度</a>给了覆盖，但单条高温链方差大。需要把 \\(N\\) 条独立样本收成一条交付。缺口是聚合函数的选择，而不是再介绍一次采样：</p><ul><li><strong>多数票</strong>：解析 \\(y\\)，取众数。无外部模型，假设错误分散。</li><li><strong>BoN</strong>：用 \\(s(x,y)\\) 取最大。上限是 \\(s\\) 的校准。</li><li><strong>MBR</strong>：用任务损失找集合中心，贵在两两度量。</li></ul><p>三者都要求样本 <em>有效多样</em>。\\(T\\to 0\\) 或共享同一束前缀，\\(N\\) 是假的。连续批与前缀缓存能让 \\(N\\) 条共享提示 KV，但 decode KV 仍近似线性于 \\(N\\)。产品把「思考」做成 \\(N=1\\) 的长链还是 \\(N=8\\) 的短链，是显存与延迟的不同曲线——后课要算的就是这条曲线。</p><p><span class="marginnote">投票在答案空间；MBR 在字符串空间。不要对未解析的思维链做多数票，也不要对 boxed 数字做 BLEU-MBR。解析规则是聚合的一部分，必须写进评测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先能解析再聚合。数学、选项、代码（测例 0/1）优先多数票或直到成功的拒绝采样。开放写作没有 \\(y\\) 的等价类，多数票无定义，应 BoN 或根本不聚合。\\(N\\) 从 4–8 扫起看边际，不要默认 64。并行采样时提示 prefill 一次，decode 分叉；串行则延迟乘 \\(N\\)，只适合离线。</p><p>与自投机 / 投机的关系：每条样本内部可以加速，但不能把 \\(N\\) 条的草稿 KV 无界堆上。结构化掩码可以每条都开，聚合前每条都合法，并不减少 \\(N\\) 的 FLOPs。</p>',11)),(a(),n(m,null,{default:t(()=>[p(o,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20PRE%5B%22%E4%B8%80%E6%AC%A1%20prefill%22%5D%0A%20%20PRE%20--%3E%20S%5B%22%E7%8B%AC%E7%AB%8B%20decode%20N%20%E6%9D%A1%22%5D%0A%20%20S%20--%3E%20P%7B%22%E6%9C%89%E5%8F%AF%E8%A7%A3%E6%9E%90%20y%3F%22%7D%0A%20%20P%20--%3E%7C%E6%98%AF%7C%20MAJ%5B%22%E5%A4%9A%E6%95%B0%E7%A5%A8%22%5D%0A%20%20P%20--%3E%7C%E5%90%A6%2C%20%E6%9C%89%20s%7C%20BON%5B%22Best-of-N%22%5D%0A%20%20P%20--%3E%7C%E5%90%A6%2C%20%E6%9C%89%20%E2%84%93%7C%20MBR%5B%22MBR%20%E4%B8%AD%E5%BF%83%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>覆盖近似 \\(1-(1-p)^N\\)，但系统性错误使众数是错的。\\(s\\) 的假阳性让 BoN 收敛到奖励黑客。<a href="/llm/diverse-beam-search">多样束</a>不能替代独立采样：相关样本让有效 \\(N\\) 下降。温度必须落在推理那一档，使 \\(y\\) 不同而不是标点不同。能量与成本随 \\(N\\) 近线性，这是下一课程用屋顶线与美元模型要接的账：投票是测试时计算，不是免费准确率。</p><p><span class="marginnote">Self-consistency 原文的 \\(N\\) 与温度是实验设置，不是产品 SLA。线上 \\(N\\) 应受 KV 池与尾延迟约束，而不是受论文表格约束。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把 \\(N=16\\) 的自洽准确率当单次模型能力。不要在开放聊天用多数票。不要在 KV 将满时对每个用户开大 \\(N\\)——应降 \\(N\\) 或拒请求。许可证与测试集：用测试规则当 \\(s\\) 是泄漏。下一课起不再讨论选哪条字符串，而讨论一条字符串的缓存有多大。</p><p>出处：Wang et al., ICLR 2023；Cobbe et al., 2021；BoN 见 Ouyang et al. InstructGPT 与 Snell et al. 2024。MBR 见本课序 <a href="/llm/mbr-decoding">MBR 解码</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>聚合在答案空间（投票）或打分器 / 度量上；先解析。</li><li>有效多样依赖 \\(T\\gt 0\\) 与独立 RNG；束的 \\(B\\) 条不是 \\(N\\)。</li><li>Prefill 可共享，decode KV 与延迟近线性于 \\(N\\)。</li><li>系统性偏差下多数票更稳地错；BoN 上限是 \\(s\\)。</li><li>结构化合法与投票正交，都要付钱。</li><li>解码进阶到此结束；下一课算 KV 字节。</li><li>出处：Wang et al., ICLR 2023；Cobbe et al., 2021。</li></ul>',8))])}const g=r(c,[["render",h]]);export{_ as __pageData,g as default};
